import{_ as e,o as a,c as s,a5 as i}from"./chunks/framework.a5no_H3L.js";const k=JSON.parse('{"title":"对象系统与编码","description":"Redis 对外提供五种核心数据类型 String、List、Hash、Set、ZSet，对内却各有多套底层编码。以 Hash 为例，数据量小时用紧凑的 listpack，数据量变大或元素变长时切换到 hashtable。类型对外的命令接口始终不变，但编码切换涉及新结构分配与数据迁移，会产生额外开销。理解编码切换的规则，才能解释 Redis 内存占用为什么省，也能在设计数据结构与成员值时避免触发不必要的编码升级。","frontmatter":{},"headers":[],"relativePath":"redis/01-data-model/chapter-05-object-encoding.md","filePath":"redis/01-data-model/chapter-05-object-encoding.md"}'),d={name:"redis/01-data-model/chapter-05-object-encoding.md"};function l(n,t,c,r,o,h){return a(),s("div",null,[...t[0]||(t[0]=[i("",76)])])}const g=e(d,[["render",l]]);export{k as __pageData,g as default};
